(function(window, document){
    function JQ(elements){
        this.elements = elements || [];
    }
    JQ.prototype.each = function(cb){
        this.elements.forEach(function(el, idx){ cb.call(el, idx, el); });
        return this;
    };
    JQ.prototype.on = function(event, selector, handler){
        if (typeof selector === 'function') {
            handler = selector;
            selector = null;
        }
        return this.each(function(){
            var el = this;
            el.addEventListener(event, function(e){
                if (!selector) {
                    handler.call(el, e);
                    return;
                }
                var target = e.target.closest(selector);
                if (target && el.contains(target)) {
                    handler.call(target, e);
                }
            });
        });
    };
    JQ.prototype.addClass = function(cls){
        return this.each(function(){ this.classList.add(cls); });
    };
    JQ.prototype.removeClass = function(cls){
        return this.each(function(){ this.classList.remove(cls); });
    };
    JQ.prototype.toggleClass = function(cls){
        return this.each(function(){ this.classList.toggle(cls); });
    };
    JQ.prototype.attr = function(name, value){
        if (value === undefined) {
            return this.elements[0] ? this.elements[0].getAttribute(name) : undefined;
        }
        return this.each(function(){ this.setAttribute(name, value); });
    };
    JQ.prototype.data = function(name, value){
        if (value === undefined) {
            return this.elements[0] ? this.elements[0].dataset[name] : undefined;
        }
        return this.each(function(){ this.dataset[name] = value; });
    };
    JQ.prototype.html = function(html){
        if (html === undefined) {
            return this.elements[0] ? this.elements[0].innerHTML : undefined;
        }
        return this.each(function(){ this.innerHTML = html; });
    };
    JQ.prototype.text = function(text){
        if (text === undefined) {
            return this.elements[0] ? this.elements[0].textContent : undefined;
        }
        return this.each(function(){ this.textContent = text; });
    };
    JQ.prototype.val = function(value){
        if (value === undefined) {
            return this.elements[0] ? this.elements[0].value : undefined;
        }
        return this.each(function(){ this.value = value; });
    };
    JQ.prototype.append = function(content){
        return this.each(function(){
            if (typeof content === 'string') {
                this.insertAdjacentHTML('beforeend', content);
            } else if (content instanceof HTMLElement) {
                this.appendChild(content);
            }
        });
    };
    JQ.prototype.prepend = function(content){
        return this.each(function(){
            if (typeof content === 'string') {
                this.insertAdjacentHTML('afterbegin', content);
            } else if (content instanceof HTMLElement) {
                this.insertBefore(content, this.firstChild);
            }
        });
    };
    JQ.prototype.empty = function(){
        return this.each(function(){ this.innerHTML = ''; });
    };
    JQ.prototype.find = function(selector){
        var found = [];
        this.each(function(){ found = found.concat([].slice.call(this.querySelectorAll(selector))); });
        return new JQ(found);
    };
    JQ.prototype.closest = function(selector){
        var el = this.elements[0] ? this.elements[0].closest(selector) : null;
        return new JQ(el ? [el] : []);
    };
    JQ.prototype.remove = function(){
        return this.each(function(){ if (this.parentNode) { this.parentNode.removeChild(this); } });
    };
    JQ.prototype.prop = function(name, value){
        if (value === undefined) {
            return this.elements[0] ? this.elements[0][name] : undefined;
        }
        return this.each(function(){ this[name] = value; });
    };
    JQ.prototype.trigger = function(event){
        return this.each(function(){
            var ev = new Event(event, { bubbles: true });
            this.dispatchEvent(ev);
        });
    };

    function $(selector){
        if (typeof selector === 'function') {
            if (document.readyState !== 'loading') {
                selector();
            } else {
                document.addEventListener('DOMContentLoaded', selector);
            }
            return;
        }
        if (selector instanceof HTMLElement || selector === window || selector === document) {
            return new JQ([selector]);
        }
        return new JQ([].slice.call(document.querySelectorAll(selector)));
    }

    $.ajax = function(options){
        var xhr = new XMLHttpRequest();
        xhr.open(options.type || 'GET', options.url, true);
        xhr.setRequestHeader('Content-Type', options.contentType || 'application/json');
        xhr.onreadystatechange = function(){
            if (xhr.readyState === 4) {
                var response = xhr.responseText;
                try { response = JSON.parse(response); } catch (e) {}
                if (xhr.status >= 200 && xhr.status < 300) {
                    if (options.success) { options.success(response); }
                } else {
                    if (options.error) { options.error(response); }
                }
            }
        };
        xhr.send(options.data ? JSON.stringify(options.data) : null);
    };

    $.getJSON = function(url, success){
        return $.ajax({ url: url, type: 'GET', success: success });
    };

    window.$ = window.jQuery = $;
})(window, document);
